insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('9e835f74-d1dd-5f28-97d3-57534700e030', 'wg3-narrative-writing-p04', (select id from public.skills where slug = 'write-g3-narrative-writing'), null,
        '3-5', $q$The Missing Puppy$q$, $q$(1) My cousin Amara and I took Biscuit, Amara's new puppy, to the park on Saturday. (2) We tossed a ball across the grass, and Biscuit chased it with floppy ears flying. (3) Then a squirrel ran past, and Biscuit slipped right out of the collar! (4) The puppy dashed behind a row of bushes.

(5) Amara's eyes filled with tears. (6) We called and called, but Biscuit did not come back. (7) Then I had an idea. (8) "Biscuit loves the squeaky ball," I said. (9) I squeezed the ball as hard as I could. (10) A moment later, a brown nose poked out of the bushes. (11) Biscuit ran straight into Amara's arms.

(12) ________$q$, 'draft')
